def encode(numbers):
    encoded = []
    for number in numbers:
        groups = [number & 0x7F]
        number >>= 7
        while number:
            groups.append((number & 0x7F) | 0x80)
            number >>= 7
        encoded.extend(reversed(groups))
    return encoded


def decode(bytes_):
    decoded = []
    value = 0
    for byte in bytes_:
        value = (value << 7) | (byte & 0x7F)
        if byte & 0x80:
            continue
        decoded.append(value)
        value = 0
    if bytes_ and bytes_[-1] & 0x80:
        raise ValueError("incomplete sequence")
    return decoded
